+use rustls_pki_types::{
+    CertificateDer, CertificateRevocationListDer, PrivatePkcs1KeyDer, PrivatePkcs8KeyDer,
+    PrivateSec1KeyDer,
+};
+use std::io;
+
+pub use rustls_pemfile_upstream::{
+    private_key, read_all, read_one, read_one_from_slice, Error, Item,
+};
+
+pub struct PemItems<T> {
+    inner: std::vec::IntoIter<Result<T, io::Error>>,
+}
+
+impl<T> Iterator for PemItems<T> {
+    type Item = Result<T, io::Error>;
+
+    fn next(&mut self) -> Option<Self::Item> {
+        self.inner.next()
+    }
+}
+
+impl<T: DerBytes> PemItems<T> {
+    pub fn expect(self, msg: &str) -> Vec<Vec<u8>> {
+        self.map(|item| item.expect(msg).der_bytes().to_vec())
+            .collect()
+    }
+
+    pub fn unwrap(self) -> Vec<Vec<u8>> {
+        self.map(|item| item.unwrap().der_bytes().to_vec())
+            .collect()
+    }
+}
+
+trait DerBytes {
+    fn der_bytes(&self) -> &[u8];
+}
+
+impl DerBytes for CertificateDer<'_> {
+    fn der_bytes(&self) -> &[u8] {
+        self.as_ref()
+    }
+}
+
+impl DerBytes for CertificateRevocationListDer<'_> {
+    fn der_bytes(&self) -> &[u8] {
+        self.as_ref()
+    }
+}
+
+impl DerBytes for PrivatePkcs1KeyDer<'_> {
+    fn der_bytes(&self) -> &[u8] {
+        self.secret_pkcs1_der()
+    }
+}
+
+impl DerBytes for PrivatePkcs8KeyDer<'_> {
+    fn der_bytes(&self) -> &[u8] {
+        self.secret_pkcs8_der()
+    }
+}
+
+impl DerBytes for PrivateSec1KeyDer<'_> {
+    fn der_bytes(&self) -> &[u8] {
+        self.secret_sec1_der()
+    }
+}
+
+pub fn certs(rd: &mut dyn io::BufRead) -> PemItems<CertificateDer<'static>> {
+    PemItems {
+        inner: rustls_pemfile_upstream::certs(rd)
+            .collect::<Vec<_>>()
+            .into_iter(),
+    }
+}
+
+pub fn crls(rd: &mut dyn io::BufRead) -> PemItems<CertificateRevocationListDer<'static>> {
+    PemItems {
+        inner: rustls_pemfile_upstream::crls(rd)
+            .collect::<Vec<_>>()
+            .into_iter(),
+    }
+}
+
